INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'Citizenship', 'Unit 4', 'Molarum Grade 10 — Citizenship Unit 4: Peace and Indigenous Conflict Resolution', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 4: Peace and Indigenous Conflict Resolution.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('8d7b5357-8f0b-4cb7-8a35-b4697b9eb1f8'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which definition from the excerpt best matches ''Rule of law'' ?', 'The mechanism, process, practice, or norm that supports the equality of all citizens before the law, and prevents the arbitrary use of power', 'The excerpt defines ''Rule of law'' as the mechanism and norms that support equality before the law and prevent arbitrary use of power, which directly matches the correct option.', 0),('3d68a00e-3177-4566-8a9b-736fed400811'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'According to the excerpt, which term is defined as ''the misuse of entrusted power for personal or private gain'' ?', 'Corruption', 'The excerpt explicitly defines ''Corruption'' as the misuse of entrusted power for personal or private gain, so ''Corruption'' is the correct choice.', 1),('a7d6bf5d-363b-4661-81d5-76a08d31485c'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which phrase in the excerpt best describes ''Social cohesion'' ?', 'The strength of relationships and the sense of solidarity among members of a community', 'The excerpt defines ''Social cohesion'' as the strength of relationships and a sense of solidarity among community members, matching the chosen option.', 2),('129c9a32-b4d0-4969-8baa-2b570f097ed6'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which of the following is described in the excerpt as ''peace within oneself'' and ''a state of calm and peacefulness of mind'' ?', 'Internal peace', 'The excerpt defines internal peace as peace within oneself, a calm state of mind without suffering or mental disturbance, which corresponds to ''Internal peace''.', 3),('c5af87cc-920f-4f05-8f48-df6908b90dd1'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which type of peace in the excerpt is defined as ''a peace without justice'' and ''the absence of direct violence or the fear of violence'' ?', 'Negative peace', 'The excerpt defines negative peace as peace without justice and as the absence of direct violence or fear of violence, so ''Negative peace'' is correct.', 4),('53e38030-a0da-4ea1-8783-3e189d799dba'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'What does the excerpt say is a feature of ''external peace'' ?', 'Absence of war, disorder, disturbances, hostility and social injustice', 'The excerpt describes external peace as a societal state that includes absence of war, disorder, disturbances, hostility and social injustice, making the first option correct.', 5),('bea93121-de6c-4d10-8b32-77e5d9401d3d'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which statement about positive peace is supported by the excerpt?', 'It is built on justice for all peoples and includes institutions that meet citizens'' needs', 'The excerpt states that positive peace is lasting and built on justice, with institutions that meet citizens'' needs and eliminate root causes of violence, matching the first option.', 6),('e487b868-3229-4302-8920-4f0d5bb19f0b'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which of the following is listed in the excerpt as a socio-economic impact of absence of peace?', 'Resources are diverted from health and education to military expenditure', 'The excerpt explains that during violent conflict resources are diverted from health, education and other social services to military expenditure, which is the correct impact.', 7),('69da3290-e31e-4261-8f73-c3f3a21f11ed'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'According to the excerpt, absence of peace can undermine cultural diversity by causing what outcome?', 'Ethnic, tribal or cultural groups compete for power and resources leading to inter-tribal oppression', 'The excerpt states that without peace, cultural diversity is at risk as groups compete for power and resources, which can lead to tribal oppression and antagonism between groups.', 8),('1414ebaf-156e-487d-81eb-2f10612f94b4'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which sentence best summarizes the excerpt''s definition of ''peace building''?', 'A long-term process encouraging conflicting parties to talk, repair relationships, and address root causes to create sustained peace', 'The excerpt defines peace building as a long-term process of encouraging dialogue, repairing relationships, and addressing root causes for sustainable peace, which the first option conveys.', 9),('4ecc584d-b51c-41e7-8eb5-f565b277c229'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which activity is listed in the excerpt as part of successful peace building?', 'Reforming justice and security institutions and promoting a culture of truth and reconciliation', 'The excerpt lists reforming justice and security institutions and promoting truth and reconciliation among successful peace-building activities, so this option is correct.', 10),('733c2911-850f-4f97-8c0d-cf9959480d9d'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'How does the excerpt describe indigenous conflict resolution mechanisms?', 'Grassroots and community-based mechanisms based on customary practices present in communities', 'The excerpt defines indigenous conflict resolution mechanisms as grassroots, community-based practices rooted in custom and tradition, which matches the first option.', 11),('51990a2a-91f8-4f08-80a6-be3a38447030'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which of the following is presented in the excerpt as a common feature of indigenous conflict resolution mechanisms?', 'Voluntary and consensual proceedings relying on social pressure rather than formal coercion', 'The excerpt states that indigenous mechanisms generally require voluntary participation and rely on social pressure and community exclusion for non-compliance, making the first option correct.', 12),('9f0687d9-2d87-4c9c-8fbf-aa172bafdc82'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which feature from the excerpt explains why indigenous mechanisms can adapt to new circumstances over time?', 'Dynamism and responsiveness to change', 'The excerpt explains that indigenous mechanisms evolve over generations and respond to changes, which is described as dynamism and responsiveness to change.', 13),('ce62b2c3-2896-4f6f-828c-532f4e03ba88'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'According to the excerpt, who usually leads the process of indigenous conflict resolution in Ethiopian communities?', 'Elders or leaders of the community who are influential and know the parties', 'The excerpt states that elders or community leaders, chosen for age, cultural knowledge and social standing, lead indigenous resolution processes in Ethiopia, making the first option correct.', 14),('f86e4142-96dd-4da1-8f94-9aea05bb0176'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which of these names is given in the excerpt as an indigenous conflict resolution mechanism in Ethiopia?', 'Xeer', 'The excerpt lists ''Xeer'' among indigenous mechanisms practiced in Ethiopia, so ''Xeer'' is the correct selection.', 15),('8f2d5aab-b727-4b75-8252-c0b628bc1693'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which role of indigenous social institutions is described in the excerpt as aiming to ''restore order and harmony'' and reintegrate deviants rather than punish them?', 'Restoration of order and relationships', 'The excerpt explains that indigenous conflict resolution focuses on restoring order and harmony and reintegrating members, which corresponds to ''Restoration of order and relationships''.', 16),('2ef334f9-3509-4640-8d55-b1999742547e'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which function is attributed to indigenous social institutions in the excerpt as addressing mental and spiritual rehabilitation after conflict?', 'Addressing psycho-social and spiritual dimensions of conflicts', 'The excerpt notes that indigenous institutions deal with spiritual aspects and mental healing through rituals and traditional healers, so the first option is correct.', 17),('2158d1e6-6bc0-4370-8cf4-53cd5c474ba6'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'What does the excerpt state about inclusion and participation within indigenous conflict resolution?', 'A solution is achieved by consensus with broad participation and is compatible with interests of all parties', 'The excerpt emphasizes that indigenous resolution seeks consensus and inclusive participation so every party finds a compatible, win-win outcome, supporting the correct option.', 18),('3355d0c1-553a-413f-8824-7848c16b7b99'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'multiple_choice', 'Which practice is noted in the excerpt as often required by indigenous conflict institutions instead of physical punishment?', 'Forgiveness and compensation', 'The excerpt explains that indigenous institutions often require the wrongdoer to ask forgiveness and/or pay compensation rather than imposing physical punishment, so ''Forgiveness and compensation'' is correct.', 19),('006d9c7e-cb19-438a-8910-16b37b18b009'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'true_false', 'The excerpt states that internal and external peace are interrelated and interdependent.', 'True', 'The ''Remember'' box in the excerpt explicitly states that internal and external peace are interrelated and interdependent, so the statement is true.', 20),('47b024b0-9fcb-426c-8e62-8b1a9b999581'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'true_false', 'The excerpt describes peace building as a short-term process that only stops fighting temporarily.', 'False', 'The excerpt describes peace building as a long-term process focused on addressing root causes and creating sustained peace, so the statement is false.', 21),('9684825f-109d-450a-8e16-bb6c834eafa0'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'true_false', 'Indigenous conflict resolution mechanisms, as described in the excerpt, are context specific and can vary between communities.', 'True', 'The excerpt lists ''Context specific'' as a feature, noting approaches vary from society to society and community to community, so the statement is true.', 22),('c2a576d7-ba82-4c25-8a77-66aded1c91cf'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'true_false', 'The excerpt claims indigenous social institutions are not accessible to the community and usually delay conflict resolution.', 'False', 'The excerpt states the opposite: indigenous social institutions are accessible and often solve conflicts immediately by consensus, so the statement is false.', 23),('41eacc4c-76ab-471f-8998-42652f742f3d'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'Define ''indigenous conflict resolution mechanisms'' as given in the excerpt.', 'Grassroots, community-based mechanisms for solving conflicts according to customary practices present in communities, rooted in culture and tradition.', 'The excerpt defines indigenous mechanisms as grassroots, community-based practices grounded in customary norms and traditions used to reconcile and maintain societal relationships.', 24),('01afe622-dcc9-4687-8ebc-9e592d5f1016'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'List two features of indigenous conflict resolution mechanisms stated in the excerpt.', 'Examples include ''voluntary and consensual proceedings'' and ''dynamism and responsiveness to change''.', 'The excerpt lists several features; among them it notes voluntary, consensual proceedings and that mechanisms evolve and respond to change, which are valid examples.', 25),('fbe52121-79d2-4492-8d58-b78a341eed84'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'What is the main aim of indigenous conflict resolution mechanisms according to the excerpt?', 'To restore peace and harmony and maintain peaceful co-existence by reconciling parties and repairing relationships.', 'The excerpt explains that indigenous mechanisms aim to restore harmony and enable parties to live together by reconciling differences rather than punishing, which is their main aim.', 26),('8382cd3c-c819-46c7-871d-71fe01ce419e'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'Explain briefly why positive peace is considered ''true, lasting, and sustainable'' in the excerpt.', 'Because positive peace addresses root causes of violence and builds institutions, attitudes and structures that meet citizens'' needs and enable non-violent dispute resolution.', 'The excerpt states positive peace involves eliminating root causes and creating institutions and attitudes that sustain peaceful societies, which explains its lasting nature.', 27),('b3768845-f91b-4db6-8c57-f4a058551483'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'According to the excerpt, name two actors (other than elders) who take part in indigenous conflict resolution processes.', 'Religious leaders and family members (also community members) participate in indigenous processes.', 'The excerpt mentions elders lead the process and also lists religious leaders, family members and community members as actors involved in resolution.', 28),('03185e37-1478-47f6-84ad-2ee44914eea1'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'Give one reason from the excerpt why indigenous institutions emphasize reconciliation over punishment.', 'Reconciliation restores social harmony and reintegrates members, avoiding further harm to the group and ensuring future cooperation.', 'The excerpt explains that reconciliation aims to restore good relations and reintegrate members, whereas punishment would harm the group a second time, which is why reconciliation is emphasized.', 29),('1a3a133c-40a6-449c-8e57-13feaa613cf4'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'According to the excerpt, how do indigenous social institutions help build community cohesion?', 'They keep community values alive, foster togetherness and solidarity, enable broad participation in judicial processes, and rely on consensus to resolve disputes.', 'The excerpt states indigenous institutions maintain values, promote solidarity and consensus-based participation which together build community cohesion.', 30),('119af85c-e9ce-4494-859a-61de223c423b'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'What role do rituals and traditional healers play in indigenous conflict resolution according to the excerpt?', 'They have symbolic and practical significance for purification, healing, and mental and spiritual rehabilitation of victims and perpetrators.', 'The excerpt explains that rituals and traditional healers perform purification and healing, supporting mental and spiritual rehabilitation during reconciliation.', 31),('48c90d36-dbf3-4382-8392-e87f050b4ab8'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'How many types of peace are explicitly named in section 4.1.1 of the excerpt?', '4', 'Section 4.1.1 lists internal (inner), external (outer), positive and negative peace, totaling four types.', 32),('fb4e512c-2567-4ea1-8374-eb0a9f31deca'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'How many features of indigenous conflict resolution mechanisms are listed under A–G in the excerpt?', '7', 'The excerpt enumerates features labelled A through G, which counts to seven distinct features.', 33),('43d71cff-ef6b-4ebc-8e7c-bdb87309d741'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'How many roles of indigenous social institutions are listed under A–E in the excerpt?', '5', 'The excerpt lists roles A through E under ''The roles of indigenous social institutions'', giving five roles in total.', 34),('61d3f95f-76fb-4355-84c7-339f86de66d2'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'How many lessons are enumerated at the start of this unit under ''Lessons'' in the excerpt?', '5', 'The excerpt lists five lessons numbered 1 to 5 at the start of the unit, so the correct number is five.', 35),('3b767648-9d6c-4370-82e6-8dbbdfd286b9'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'According to the excerpt, how many impacts of absence of peace are presented under sections A–E?', '5', 'The ''Impacts of absence of peace'' section lists five subsections labelled A through E, totaling five impacts.', 36),('2921633d-12ce-40bf-804a-1c6c5cd8c5f7'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'How many learning outcomes are listed at the start of the unit under ''At the end of this unit, you will be able to:''?', '5', 'The excerpt lists five learning outcomes in that section, so the number of learning outcomes is five.', 37),('7747ecb6-5690-4ef9-8eb8-26a497165caf'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'The excerpt states ''Ethiopia is believed to be a country of more than ___ ethnic groups.'' What number completes this sentence exactly as given in the excerpt?', '80', 'The excerpt states Ethiopia has ''more than 80 ethnic groups'', so the number appearing in the sentence is 80.', 38),('dbfbb4b5-d14b-4249-813f-a51c315e01ca'::uuid, 'b89c90e2-f639-4204-8e17-82c313d549b5'::uuid, 'fill_blank', 'In Part III of the unit review exercises, how many items under column A are to be matched with items under B?', '5', 'Part III shows five numbered items under column A to be matched with concepts in column B, so the quantity is five.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('0a3e7c86-76b8-4918-89c3-ad614d4cec3f'::uuid, '8d7b5357-8f0b-4cb7-8a35-b4697b9eb1f8'::uuid, 'The mechanism, process, practice, or norm that supports the equality of all citizens before the law, and prevents the arbitrary use of power', TRUE, 0),('b396ca2c-764d-4004-8741-b58e561793dd'::uuid, '8d7b5357-8f0b-4cb7-8a35-b4697b9eb1f8'::uuid, 'The misuse of entrusted power for personal or private gain', FALSE, 1),('e09693a0-f886-4983-862b-211e2ed508e5'::uuid, '8d7b5357-8f0b-4cb7-8a35-b4697b9eb1f8'::uuid, 'The strength of relationships and the sense of solidarity among members of a community', FALSE, 2),('f555a539-c0b1-4738-8512-ba26f18288d6'::uuid, '8d7b5357-8f0b-4cb7-8a35-b4697b9eb1f8'::uuid, 'The process of decision making and the process by which decisions are implemented', FALSE, 3),('8b117da7-c3db-4467-8981-60298b846d89'::uuid, '3d68a00e-3177-4566-8a9b-736fed400811'::uuid, 'Corruption', TRUE, 0),('23c5c00f-1552-4ae0-845f-8ae6792a10e8'::uuid, '3d68a00e-3177-4566-8a9b-736fed400811'::uuid, 'Civil service', FALSE, 1),('f56b70da-4cb3-4fd8-8107-3104d1306dd0'::uuid, '3d68a00e-3177-4566-8a9b-736fed400811'::uuid, 'Social cohesion', FALSE, 2),('2de5a6fa-82aa-40cd-868f-c1b593c4c2a9'::uuid, '3d68a00e-3177-4566-8a9b-736fed400811'::uuid, 'Good governance', FALSE, 3),('2ea7dfbd-e97f-4ee6-850e-716226004803'::uuid, 'a7d6bf5d-363b-4661-81d5-76a08d31485c'::uuid, 'The strength of relationships and the sense of solidarity among members of a community', TRUE, 0),('756c00b7-78c3-4fc0-8804-32b9e63ca303'::uuid, 'a7d6bf5d-363b-4661-81d5-76a08d31485c'::uuid, 'The equal and fair distribution of wealth, opportunities and privileges within a society', FALSE, 1),('6a84a19a-12c7-4232-85a8-37f044f9d16a'::uuid, 'a7d6bf5d-363b-4661-81d5-76a08d31485c'::uuid, 'Government carries out the works of government and delivers public services', FALSE, 2),('b66c14d5-1a09-4249-8a15-bf3f69b9377d'::uuid, 'a7d6bf5d-363b-4661-81